#!/usr/bin/env node
// what-it-is:   the guard on every hand-typed run-envelope count in the front-door documents
// what-it-does: counts the committed run envelopes on disk and asserts that every "<n> run
//               envelopes" / "<n> committed run envelopes" figure in README.md and ROADMAP.md
//               names that same number
// why:          the README's scoreboard block is generated by `python -m bench.report scoreboard`
//               and drift-checked, while the badge, the routing table, the receipts paragraph and
//               the Fast-facts row beside it are hand-typed. That is the same shape of defect the
//               repository has hit repeatedly: a guard exists for one twin and not the other, and
//               every stale figure lands in the unguarded twin. Measured 2026-09-14, four places
//               said 502 while the tree held 541, across README.md and ROADMAP.md
// used-by:      scripts/check.mjs, which runs it UNCONDITIONALLY
//
// Usage:  node scripts/check-readme-figures.mjs
// Exit:   0 = every typed envelope count matches the tree; 1 = at least one does not.
//
// Scope, deliberately narrow. This guards the envelope count and nothing else, because the envelope
// count is the only one of these figures derivable WITHOUT running anything: it is a property of
// committed files. Test counts are knowable only by running the suites, so a guard for them would
// either duplicate the unit-python and unit-node jobs or trust a second hand-typed number, and both
// are worse than not publishing an exact figure. See the Fast-facts row for what is published
// instead.
import { readFileSync, existsSync, readdirSync, statSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(HERE, "..");

/** The run-root glob contract/validate_envelopes.py uses. Kept identical on purpose. */
const RUN_ROOT_PREFIX = "runs";

/**
 * Every shape the envelope count appears in across the front-door documents. Prose is the common
 * one; the shields.io badge and its alt text are the other two, and they are the most visible
 * figure in the repository, so a guard that skipped them would miss the one a reader sees first.
 */
const FIGURES = [
  /(\d[\d,]*)(?=\s+(?:committed\s+)?run\s+envelopes)/gi, // "541 run envelopes", "541 committed run envelopes"
  /run%20envelopes-(\d[\d,]*)-/gi, //                       the shields.io badge value
  /Run envelopes:\s*(\d[\d,]*)/gi, //                       the badge's alt text
];

/** Recursively count `*.json` files under one run root, excluding `.raw.txt` sidecars. */
function countJson(dir) {
  let n = 0;
  for (const entry of readdirSync(dir)) {
    const p = join(dir, entry);
    if (statSync(p).isDirectory()) n += countJson(p);
    else if (entry.endsWith(".json")) n += 1;
  }
  return n;
}

/** Count every committed envelope, the way the validator discovers them. */
export function countEnvelopes(resultsDir = join(ROOT, "bench", "results")) {
  if (!existsSync(resultsDir)) return 0;
  let total = 0;
  for (const entry of readdirSync(resultsDir)) {
    if (!entry.startsWith(RUN_ROOT_PREFIX)) continue;
    const p = join(resultsDir, entry);
    if (statSync(p).isDirectory()) total += countJson(p);
  }
  return total;
}

export function checkReadmeFigures({ files, resultsDir } = {}) {
  const actual = countEnvelopes(resultsDir);
  const targets = files || [join(ROOT, "README.md"), join(ROOT, "ROADMAP.md")];

  console.log("=== Front-door figures ===");
  if (actual === 0) {
    console.error("FAIL: found no committed run envelopes; refusing to validate against zero.");
    return 1;
  }

  const bad = [];
  let checked = 0;
  for (const file of targets) {
    if (!existsSync(file)) {
      console.error(`FAIL: ${file} does not exist.`);
      return 1;
    }
    const lines = readFileSync(file, "utf8").split(/\r?\n/);
    lines.forEach((line, i) => {
      for (const pattern of FIGURES) {
        for (const m of line.matchAll(pattern)) {
          checked += 1;
          const typed = Number(m[1].replace(/,/g, ""));
          if (typed !== actual) {
            bad.push({
              file: file.replace(ROOT + "\\", "").replace(ROOT + "/", ""),
              line: i + 1,
              typed,
            });
          }
        }
      }
    });
  }

  if (bad.length) {
    console.error(
      `FAIL: ${bad.length} of ${checked} typed envelope count(s) disagree with the ${actual} on disk.`,
    );
    for (const b of bad) console.error(`  ${b.file}:${b.line} says ${b.typed}, tree holds ${actual}`);
    console.error("  Fix the prose, or regenerate whatever wrote it. The tree is the source of truth.");
    return 1;
  }

  console.log(`envelope counts checked: ${checked}   committed envelopes on disk: ${actual}`);
  console.log("\nPASS: every typed run-envelope figure matches the committed tree.");
  return 0;
}

if (import.meta.url === `file://${process.argv[1]}` || process.argv[1]?.endsWith("check-readme-figures.mjs")) {
  process.exit(checkReadmeFigures());
}
